      "claim": "Vehicle_status brake and vehicle_cmd brake are always zero in the collision window, and speed does not decrease, indicating no braking response before impact."
    },
    {
      "evidence_id": "critical_window_summary.collision_window.final_waypoints_before_collision",
      "claim": "Final waypoints exist with 101 waypoints per row, zero blocked_waypoint events, and the last pre-collision row has waypoint_count=101 and is_blocked=false."
    },
    {
      "evidence_id": "trace_summary_compact.planning.final_waypoints",
      "claim": "Planner outputs final_waypoints from about 11.67s to 25.17s with a consistent count of 101 and no blocked rows or null entries in the sampled data."
