      "evidence_id": "critical_window_summary.collision_window.detected_object_count_before_collision",
      "claim": "Detection objects are present in the collision window with 1–6 objects and labels including car and person, showing that some perception outputs exist before the collision."
    },
    {
      "evidence_id": "critical_window_summary.collision_window.predicted_object_count_before_collision",
      "claim": "Prediction objects are present with 1–13 objects and labels such as car and person in the collision window, indicating ongoing prediction activity."
    },
    {
      "evidence_id": "trace_summary_compact.actuation.vehicle_cmd",
      "claim": "Vehicle_cmd exists from ~7.87s to 25.17s but all accel_cmd, brake_cmd, steer_cmd, and target_speed values are zero across the sampled range."
    },
    {
      "evidence_id": "trace_summary_compact.actuation.vehicle_status",
      "claim": "Vehicle_status shows nonzero velocity (up to ~0.1075, in Autoware units), nonzero throttle, and zero brake, indicating the ego is moving despite the zeroed vehicle_cmd."
    },
    {
      "evidence_id": "trace_summary_compact.oracle.collision",
      "claim": "Collision topic exists with crash timestamps around 24.67–25.17s and significant impulse magnitudes, confirming that a collision occurred."
    }
  ],
